sn_aia_tool.script:
(function(inputs) {
    var T = 'x_snc_ptag_engage_engagement_request';
    var gr = new GlideRecord(T);
    if (!inputs || !inputs.request_sys_id || !gr.get(inputs.request_sys_id)) {
        return JSON.stringify({error: 'record not found: ' + (inputs && inputs.request_sys_id)});
    }
    function plain(v, max) {
        var t = ('' + (v || '')).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ')
            .replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
        return t.length > max ? t.substring(0, max) + '...' : t;
    }
    function yn(f) { return gr.getValue(f) === '1' ? 'confirmed' : 'not confirmed at intake'; }
    function dv(f) {
        var s = '' + gr.getDisplayValue(f);
        return (s && s !== 'null' && s !== 'undefined') ? s : 'Not provided';
    }
    var BAND = {fast_track: 'Fast Track', standard: 'Standard', needs_development: 'Needs Development'};
    var band = gr.getValue('score_band') || '';
    var pain = plain(gr.getValue('customer_pain_points'), 500);
    var vprop = plain(gr.getValue('value_prop'), 500);
    var strat = plain(gr.getValue('what_is_the_partners_ai_strategy'), 500);
    var idea = plain(gr.getValue('idea_description'), 500);
    var out = {
        number: gr.getValue('number'),
        short_description: gr.getValue('short_description') || '(empty)',
        partner: dv('partner'), practice: dv('practice'),
        geo: dv('target_geo'), route: dv('route_to_market'),
        stamped_assessment: {
            score: gr.getValue('score') || 'not yet stamped',
            band_label: BAND[band] || band || 'not yet stamped',
            scoring_version: gr.getValue('scoring_version') || '0'
        },
        desirability: {
            customer_pain_points: {chars: pain === 'Not provided' ? 0 : pain.length, head: pain || '(empty)'},
            value_proposition: {chars: vprop === 'Not provided' ? 0 : vprop.length, head: vprop || '(empty)'},
            existing_customers: yn('has_customers')
        },
        viability: {
            tam: dv('tam'), budget: yn('budget'), pipeline: yn('pipeline'),
            executive_sponsor: yn('executive_sponsor'), business_owner: yn('business_owner'),
            corporate_alignment: yn('corporate_alignment')
        },
        feasibility: {
            maturity: dv('in_market_status'), certified_resources: yn('certified_resources'),
            partner_ai_strategy: {chars: strat === 'Not provided' ? 0 : strat.length, head: strat || '(empty)'},
            primary_product: dv('primary_product')
        },
        engagement_description: {chars: idea === 'Not provided' ? 0 : idea.length, head: idea || '(empty)'}
    };
    return JSON.stringify(out);
})(inputs);
